// spec: specs/orders.md §35 · кейс .qa/tests/orders/ord-48-items-sorted-by-name-everywhere.md · seed: tests/seed.admin.spec.ts / tests/seed.buyer.spec.ts
// #b75d3b (עבר QA 19.11): одно правило порядка позиций — по названию товара (числа в названии — как числа) везде:
//   карточка заказа, קבלה (экран и печать), תעודת משלוח (экран и печать), страница заказа покупателя /shop/order/<id>.
//   Заказ #684 (c294c18b-…, buyer «test», ₪19.00): 1) «באמפר קטן (30 יח)» ×1 ₪9.00, 2) «מצית קליפט» ×2 ₪5.00 (מק"ט 5710840209437).
//   Было: в קבלה порядок обратный карточке, на экране קבלה מק"ט без заголовка. Теперь: «מק"ט: 5710840209437» у «מצית קליפט»,
//   у «באמפר קטן» строки מק"ט нет; итоги: סה"כ פריטים 3, לפני מע"מ ₪16.10, מע"מ 18% ₪2.90, סה"כ כולל מע"מ ₪19.00.
// Только чтение (заказ и קבלה #1 существуют; новые не создаются) → @prod-safe. Печать — emulateMedia print.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

const ORDER = 'c294c18b-56fb-4725-ab8c-a36d8c9502e1'; // #684
const FIRST = 'באמפר קטן (30 יח)';
const SECOND = 'מצית קליפט';
const SKU = '5710840209437';
const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);
const BIDI = /[‎‏‪-‮⁦-⁩]/g;
const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const norm = (s: string) => s.replace(BIDI, '').replace(/[ \t]+/g, ' ');

/** Позиции FIRST и SECOND идут в таком порядке в тексте (после маркера, если задан). */
function expectOrder(text: string, after?: string) {
  const t = norm(text);
  const from = after ? t.indexOf(after) : 0;
  expect(from, `маркер «${after}» найден`).toBeGreaterThanOrEqual(0);
  const a = t.indexOf(FIRST, from);
  const b = t.indexOf(SECOND, from);
  expect(a, `«${FIRST}» найден`).toBeGreaterThanOrEqual(0);
  expect(b, `«${SECOND}» найден`).toBeGreaterThanOrEqual(0);
  expect(a, `«${FIRST}» выше «${SECOND}»`).toBeLessThan(b);
}

const mainText = (page: Page) => page.getByRole('main').innerText();

/** Печатная таблица pd-table: названия в строках (кроме строки штрихкода). */
const printNames = (page: Page) => page.evaluate(() =>
  [...document.querySelectorAll('table.pd-table tbody tr:not(.pd-barcode-row)')]
    .map((r) => (r.querySelector('td') as HTMLElement).textContent!.trim()).filter(Boolean));

test.describe('סדר פריטים לפי שם — admin (#b75d3b)', () => {
  test.use({ storageState: auth('admin') });

  test('כרטיס הזמנה #684: «באמפר קטן (30 יח)» לפני «מצית קליפט» #b75d3b @desktop @prod-safe', async ({ page }) => {
    await page.goto(`/orders/${ORDER}`);
    await expect(page.getByRole('heading', { level: 1, name: 'הזמנה #684' })).toBeVisible({ timeout: 30_000 });
    await expect(page.getByRole('main').getByText(SECOND, { exact: true })).toBeVisible();
    expectOrder(await mainText(page), 'פריטי ההזמנה');
  });

  test('קבלה #1 (מסך): אותו סדר; «מק"ט: 5710840209437» ליד «מצית קליפט», ל«באמפר קטן» אין שורת מק"ט; סיכומים ₪19.00 / 16.10 / 2.90 #b75d3b @desktop @prod-safe', async ({ page }) => {
    await page.goto(`/orders/${ORDER}/receipt`);
    await expect(page.getByRole('heading', { level: 1, name: 'קבלה #1 · הזמנה #684' })).toBeVisible({ timeout: 30_000 });
    await expect(page.getByRole('main').getByText(SECOND, { exact: true })).toBeVisible();
    const text = norm(await mainText(page));
    expectOrder(text, 'מנפיק');
    expect(text, '«מק"ט: …» — подпись у מצית קליפט').toMatch(new RegExp(`${esc(SECOND)}\\n+מק"ט: ${SKU}\\n+2 × ₪5\\.00\\n+₪10\\.00`));
    expect(text.match(/מק"ט:/g) ?? [], 'строка «מק"ט:» одна — у באמפר её нет').toHaveLength(1);
    expect(text).toMatch(new RegExp(`${esc(FIRST)}\\n+1 × ₪9\\.00\\n+₪9\\.00\\n+${esc(SECOND)}`));
    expect(text).toMatch(/סה"כ פריטים\n+3\n+לפני מע"מ\n+₪16\.10\n+מע"מ 18%\n+₪2\.90\n+סה"כ כולל מע"מ\n+₪19\.00/);
  });

  test('קבלה #1 (הדפסה): טבלת pd-table — אותו סדר, עמודת מק"ט: «—» / 5710840209437, סכומים זהים #b75d3b @desktop @prod-safe', async ({ page }) => {
    await page.goto(`/orders/${ORDER}/receipt`);
    await expect(page.getByRole('heading', { level: 1, name: 'קבלה #1 · הזמנה #684' })).toBeVisible({ timeout: 30_000 });
    await page.emulateMedia({ media: 'print' });
    await expect(page.locator('table.pd-table')).toBeVisible();
    expect(await printNames(page)).toEqual([FIRST, SECOND]);
    const rows = await page.evaluate(() => [...document.querySelectorAll('table.pd-table tbody tr')].map((r) => [...r.cells].map((c) => (c.textContent || '').trim())));
    expect(rows).toEqual([[FIRST, '—', '1', '₪9.00', '₪9.00'], [SECOND, SKU, '2', '₪5.00', '₪10.00']]);
    const body = norm(await page.evaluate(() => document.body.innerText));
    for (const s of ['סה״כ פריטים: 3', 'לפני מע״מ: ₪16.10', 'מע״מ 18%: ₪2.90', 'סה״כ כולל מע״מ: ₪19.00']) expect(body).toContain(s);
  });

  test('תעודת משלוח #684 (מסך והדפסה): אותו סדר, סה״כ ₪19.00 #b75d3b @desktop @prod-safe', async ({ page }) => {
    await page.goto(`/delivery/${ORDER}`);
    await expect(page.getByRole('heading', { level: 1, name: 'תעודת משלוח · הזמנה #684' })).toBeVisible({ timeout: 30_000 });
    await expect(page.getByRole('main').getByText(SECOND, { exact: true }).first()).toBeVisible();
    expectOrder(await mainText(page), 'שם פריט');
    await page.emulateMedia({ media: 'print' });
    await expect(page.locator('table.pd-table')).toBeVisible();
    expect(await printNames(page)).toEqual([FIRST, SECOND]);
    expect(norm(await page.evaluate(() => document.body.innerText))).toContain('סה״כ לתשלום: ₪19.00');
  });
});

test.describe('סדר פריטים לפי שם — לקוח (#b75d3b)', () => {
  test.use({ storageState: auth('buyer') });

  test('דף ההזמנה בחנות /shop/order/<id>: «באמפר קטן (30 יח)» לפני «מצית קליפט», ₪19.00 #b75d3b @desktop @prod-safe', async ({ page }) => {
    await page.goto(`/shop/order/${ORDER}`);
    await expect(page.getByRole('heading', { name: 'הזמנה #684' })).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText(SECOND, { exact: true })).toBeVisible();
    const text = norm(await page.locator('body').innerText());
    expectOrder(text, 'פריטים');
    expect(text).toContain('₪19.00');
  });
});
